// services/auth.js
import api from './api';

export const login = async (email, password) => {
  try {
    const response = await api.post('/auth/login', { email, password });
    
    if (response.token && response.user) {
      localStorage.setItem('token', response.token);
      localStorage.setItem('user', JSON.stringify(response.user));
      return response;
    }
    
    throw new Error('Authentication failed');
  } catch (error) {
    throw error;
  }
};

export const register = async (userData) => {
  try {
    const response = await api.post('/auth/register', userData);
    
    if (response.token && response.user) {
      localStorage.setItem('token', response.token);
      localStorage.setItem('user', JSON.stringify(response.user));
      return response;
    }
    
    throw new Error('Registration failed');
  } catch (error) {
    throw error;
  }
};

export const logout = () => {
  localStorage.removeItem('token');
  localStorage.removeItem('user');
  window.location.href = '/login';
};

export const getCurrentUser = () => {
  const user = localStorage.getItem('user');
  return user ? JSON.parse(user) : null;
};

export const isAuthenticated = () => {
  return !!localStorage.getItem('token');
};

export const checkAuth = async () => {
  if (!isAuthenticated()) return false;
  
  try {
    const response = await api.get('/auth/me');
    localStorage.setItem('user', JSON.stringify(response.user));
    return true;
  } catch (error) {
    logout();
    return false;
  }
};

// Get user info from localStorage
export const getUserInfo = () => {
  const userString = localStorage.getItem('user');
  if (userString) {
    try {
      return JSON.parse(userString);
    } catch (e) {
      console.error('Error parsing user info from localStorage:', e);
      return null;
    }
  }
  return null;
};

// Update user password
export const updatePassword = async (currentPassword, newPassword) => {
  try {
    const token = localStorage.getItem('token');
    
    if (!token) {
      throw new Error('Authentication required');
    }
    
    const res = await axios.put(
      `${API_URL}/auth/password`,
      {
        currentPassword,
        newPassword
      },
      {
        headers: {
          'x-auth-token': token
        }
      }
    );
    
    return res.data;
  } catch (err) {
    throw err.response?.data?.message || 'Failed to update password. Please try again.';
  }
};

// Update user profile
export const updateProfile = async (profileData) => {
  try {
    const token = localStorage.getItem('token');
    
    if (!token) {
      throw new Error('Authentication required');
    }
    
    const res = await axios.put(
      `${API_URL}/auth/profile`,
      profileData,
      {
        headers: {
          'x-auth-token': token
        }
      }
    );
    
    if (res.data) {
      // Update user info in localStorage
      localStorage.setItem('user', JSON.stringify(res.data));
      return res.data;
    }
    
    throw new Error('Profile update failed');
  } catch (err) {
    throw err.response?.data?.message || 'Failed to update profile. Please try again.';
  }
};

// Request password reset
export const forgotPassword = async (email) => {
  try {
    const res = await axios.post(`${API_URL}/auth/forgot-password`, { email });
    return res.data;
  } catch (err) {
    throw err.response?.data?.message || 'Failed to request password reset. Please try again.';
  }
};

// Reset password with token
export const resetPassword = async (token, password) => {
  try {
    const res = await axios.post(`${API_URL}/auth/reset-password/${token}`, { password });
    return res.data;
  } catch (err) {
    throw err.response?.data?.message || 'Failed to reset password. Please try again.';
  }
};
